import java.util.StringJoiner;

public final class BubbleSort {
    private static final String SORTED_ARRAY_LABEL = "Sorted array: ";

    private BubbleSort() {
    }

    private static void sort(int[] values) {
        for (int pass = 0; pass < values.length - 1; pass++) {
            boolean swapped = false;

            for (int leftIndex = 0; leftIndex < values.length - pass - 1; leftIndex++) {
                if (isOutOfOrder(values, leftIndex)) {
                    swap(values, leftIndex, leftIndex + 1);
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }
    }

    private static boolean isOutOfOrder(int[] values, int leftIndex) {
        return values[leftIndex] > values[leftIndex + 1];
    }

    private static void swap(int[] values, int firstIndex, int secondIndex) {
        int temp = values[firstIndex];
        values[firstIndex] = values[secondIndex];
        values[secondIndex] = temp;
    }

    private static void printValues(int[] values) {
        System.out.println(formatValues(values));
    }

    private static String formatValues(int[] values) {
        StringJoiner formattedValues = new StringJoiner(" ");

        for (int value : values) {
            formattedValues.add(String.valueOf(value));
        }

        return formattedValues.toString();
    }

    public static void main(String[] args) {
        int[] values = sampleValues();

        sort(values);
        System.out.println(SORTED_ARRAY_LABEL);
        printValues(values);
    }

    private static int[] sampleValues() {
        return new int[] {64, 34, 25, 12, 22, 11, 90};
    }
}
